24: function hash(x,y){let v=Math.sin(x*127.1+y*311.7+21.7)*43758.5453;return v-Math.floor(v)}
25: function noise(x,y){let a=hash(Math.floor(x),Math.floor(y)),b=hash(Math.ceil(x),Math.floor(y)),c=hash(Math.floor(x),Math.ceil(y)),d=hash(Math.ceil(x),Math.ceil(y)),u=x-Math.floor(x),v=y-Math.floor(y);u=u*u*(3-2*u);v=v*v*(3-2*v);return (a*(1-u)+b*u)*(1-v)+(c*(1-u)+d*u)*v}
26: function biomeAt(x,y){let n=noise(x*.075,y*.075);if(y>24+8*Math.sin(x*.09))return 4;if(x>32+5*Math.sin(y*.08))return 2;if(x< -27+4*Math.sin(y*.1))return 3;if(y< -30+6*Math.cos(x*.1))return 1;if(Math.abs(x-12)+Math.abs(y+18)<6)return 5;return n>.86&&Math.abs(x)<20?1:0}
27: function colorTile(b,n){let colors=[['#34523c','#3d6045','#385940','#456749'],['#35584f','#3c6455','#335149','#426252'],['#776443','#876f49','#79694b','#92784c'],['#718580','#81928b','#72817e','#9aa39a'],['#49726a','#4b7f75','#49776e','#56857b'],['#5b5744','#686249','#615a46','#776b4d']][b];return colors[Math.min(3,Math.floor(n*4))]}
28: function proj(x,y,z=0){return {x:W*.5+(x-y)*tileW*.5,y:H*.53+(x+y)*tileH*.5-z}}
29: function drawBackground(t){let sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#6a8c86');sky.addColorStop(.38,'#b1aa83');sky.addColorStop(.67,'#6c795a');sky.addColorStop(1,'#243b30');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);let sunX=W*(.69+.02*Math.sin(t*.035)),sunY=H*.2;let glow=ctx.createRadialGradient(sunX,sunY,5,sunX,sunY,H*.52);glow.addColorStop(0,'rgba(255,230,167,.57)');glow.addColorStop(.18,'rgba(228,196,131,.2)');glow.addColorStop(1,'rgba(237,211,162,0)');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H*.85);ctx.fillStyle='#ffedc2';ctx.globalAlpha=.72;ctx.beginPath();ctx.arc(sunX,sunY,22,0,7);ctx.fill();ctx.globalAlpha=1;
