33: function diamond(p,color,stroke){ctx.beginPath();ctx.moveTo(p.x,p.y-tileH/2);ctx.lineTo(p.x+tileW/2,p.y);ctx.lineTo(p.x,p.y+tileH/2);ctx.lineTo(p.x-tileW/2,p.y);ctx.closePath();ctx.fillStyle=color;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=.6;ctx.stroke()}}
34: function tree(x,y,b,n){let p=proj(x-state.x,y-state.y);if(p.x<-50||p.x>W+50||p.y<-90||p.y>H+30)return;let s=.72+hash(x*2,y*4)*.7;if(b===3)s*=.85;ctx.fillStyle='#182a22';ctx.globalAlpha=.25;ctx.beginPath();ctx.ellipse(p.x+5,p.y+5,14*s,5*s,0,0,7);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle=b===3?'#685c4b':'#604a32';ctx.fillRect(p.x-3*s,p.y-22*s,6*s,25*s);let greens=b===1?['#27463c','#315849','#3a6652']:b===2?['#72603e','#8b7045','#9a7a4d']:b===3?['#43584c','#50665a','#63756a']:['#234a34','#2e5a3b','#3d6a43'];for(let i=0;i<3;i++){ctx.beginPath();ctx.moveTo(p.x,p.y-(65-i*13)*s);ctx.lineTo(p.x-(21-i*3)*s,p.y-(31-i*12)*s);ctx.lineTo(p.x+(21-i*3)*s,p.y-(31-i*12)*s);ctx.closePath();ctx.fillStyle=greens[(i+Math.floor(n*3))%greens.length];ctx.fill();ctx.strokeStyle='#b8c17b22';ctx.lineWidth=1;ctx.stroke()}if(hash(x+39,y)<.08){ctx.fillStyle='#f0c77c';ctx.beginPath();ctx.arc(p.x+12*s,p.y-40*s,2.1,0,7);ctx.fill()}}
35: function rock(x,y,n,b){let p=proj(x-state.x,y-state.y);if(p.x<-40||p.x>W+40||p.y<-50||p.y>H+50)return;let s=.55+hash(x,y+20)*.65;ctx.fillStyle='#17221c55';ctx.beginPath();ctx.ellipse(p.x,p.y+2,11*s,5*s,0,0,7);ctx.fill();ctx.beginPath();ctx.moveTo(p.x-10*s,p.y);ctx.lineTo(p.x-7*s,p.y-10*s);ctx.lineTo(p.x+1*s,p.y-16*s);ctx.lineTo(p.x+10*s,p.y-7*s);ctx.lineTo(p.x+11*s,p.y);ctx.closePath();ctx.fillStyle=b===3?'#aab0a6':b===2?'#9c8b6a':'#818b7e';ctx.fill();ctx.fillStyle='#ffffff2b';ctx.beginPath();ctx.moveTo(p.x-7*s,p.y-9*s);ctx.lineTo(p.x+1*s,p.y-15*s);ctx.lineTo(p.x+2*s,p.y-6*s);ctx.closePath();ctx.fill()}
36: function drawTile(x,y,b,n){let p=proj(x-state.x,y-state.y);if(p.x<-tileW||p.x>W+tileW||p.y<-tileH||p.y>H+tileH)return;diamond(p,colorTile(b,n));if(b===4){ctx.fillStyle='rgba(28,92,95,.55)';ctx.beginPath();ctx.ellipse(p.x,p.y,8,2,0,0,7);ctx.fill()}if(b===5&&hash(x+2,y)<.15){ctx.fillStyle='#65583f';ctx.fillRect(p.x-7,p.y-7,13,7);ctx.fillStyle='#b1a178';ctx.fillRect(p.x-5,p.y-8,3,4)}if(b===1&&hash(x,y+8)<.2){ctx.strokeStyle='#8caa87';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x-1,p.y-12);ctx.moveTo(p.x,p.y-5);ctx.lineTo(p.x-6,p.y-10);ctx.stroke()}}
37: function drawWater(t){for(let y=-42;y<43;y++)for(let x=-42;x<43;x++){let wx=Math.round(state.x)+x,wy=Math.round(state.y)+y,b=biomeAt(wx,wy),n=hash(wx,wy);drawTile(wx,wy,b,n);if(b===4&&n<.11)ctx.fillStyle='#d5e0bb55',ctx.fillRect(proj(wx-state.x,wy-state.y).x-2,proj(wx-state.x,wy-state.y).y-1,4,1)}}
38: function drawProps(){let cx=Math.floor(state.x),cy=Math.floor(state.y);let props=[];for(let y=cy-24;y<cy+24;y++)for(let x=cx-24;x<cx+24;x++){let b=biomeAt(x,y),n=hash(x+91,y+8);if(n<.18&&b!==4&&b!==5)props.push({x,y,b,n,type:'tree'});else if(n>.7&&n<.82)props.push({x,y,b,n,type:'rock'});else if(n>.88)props.push({x,y,b,n,type:'flower'})}props.sort((a,b)=>(a.x+a.y)-(b.x+b.y));for(let o of props){if(o.type==='tree')tree(o.x,o.y,o.b,o.n);else if(o.type==='rock')rock(o.x,o.y,o.n,o.b);else{let p=proj(o.x-state.x,o.y-state.y);ctx.fillStyle=['#e8c977','#d9909e','#b7cc8b'][Math.floor(o.n*3)];ctx.beginPath();ctx.arc(p.x,p.y-4,2,0,7);ctx.fill()}}}
39: function drawShelter(){let p=proj(state.x+3-state.x,state.y+1-state.y);ctx.fillStyle='#573f30';ctx.beginPath();ctx.moveTo(p.x-28,p.y);ctx.lineTo(p.x,p.y-36);ctx.lineTo(p.x+29,p.y);ctx.closePath();ctx.fill();ctx.fillStyle='#8b6541';ctx.beginPath();ctx.moveTo(p.x-29,p.y);ctx.lineTo(p.x,p.y-37);ctx.lineTo(p.x+3,p.y+1);ctx.closePath();ctx.fill();ctx.fillStyle='#27332a';ctx.fillRect(p.x-6,p.y-16,11,16)}
40: function drawPlayer(t){let p=proj(0,0);let bob=Math.sin(t*.008)*2;ctx.fillStyle='#10181266';ctx.beginPath();ctx.ellipse(p.x,p.y+5,13,6,0,0,7);ctx.fill();ctx.save();ctx.translate(p.x,p.y+bob);ctx.fillStyle=['#344b45','#496447','#72543c'][state.clothes%3];ctx.beginPath();ctx.moveTo(-9,-7);ctx.lineTo(0,-29);ctx.lineTo(9,-7);ctx.lineTo(8,0);ctx.lineTo(-8,0);ctx.closePath();ctx.fill();ctx.fillStyle=state.skin||'#cfaa82';ctx.beginPath();ctx.arc(0,-33,6.3,0,7);ctx.fill();ctx.fillStyle=state.hairColor||['#302a25','#573b2d','#b99258'][state.hair%3];ctx.beginPath();ctx.arc(0,-36,6.2,Math.PI,0);ctx.lineTo(6,-32);ctx.lineTo(-6,-32);ctx.closePath();ctx.fill();ctx.strokeStyle='#c8c0a3';ctx.lineWidth=2.5;ctx.beginPath();ctx.moveTo(8,-16);ctx.lineTo(14,-31);ctx.stroke();ctx.strokeStyle='#e3d8b8';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(12,-34);ctx.lineTo(16,-43);ctx.stroke();ctx.restore();if(attackFlash>0){ctx.strokeStyle=`rgba(255,218,139,${attackFlash})`;ctx.lineWidth=4;ctx.beginPath();ctx.arc(p.x,p.y-20,34,-1.3,1.5);ctx.stroke()}}
41: function drawMobs(t){let spots=[];for(let y=-17;y<18;y++)for(let x=-17;x<18;x++){if(hash(x+333,y+722)<.005)spots.push({x:Math.round(state.x)+x,y:Math.round(state.y)+y})}for(let m of spots){let p=proj(m.x-state.x,m.y-state.y);let b=biomeAt(m.x,m.y);ctx.fillStyle='#17201677';ctx.beginPath();ctx.ellipse(p.x,p.y+3,10,4,0,0,7);ctx.fill();ctx.fillStyle=b===3?'#596568':b===1?'#6c8774':'#68714b';ctx.beginPath();ctx.arc(p.x,p.y-9,8,0,7);ctx.fill();ctx.fillStyle='#da7158';ctx.fillRect(p.x-4,p.y-11,2,2);ctx.fillRect(p.x+2,p.y-11,2,2)}}
42: function drawParticles(){for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.y-=p.v;p.life-=.018;ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,7);ctx.fill();if(p.life<=0)particles.splice(i,1)}ctx.globalAlpha=1}
43: function drawMap(){let w=mapC.width,h=mapC.height;mctx.fillStyle='#263a31';mctx.fillRect(0,0,w,h);for(let y=0;y<h;y+=4)for(let x=0;x<w;x+=4){let wx=state.x+(x-w/2)/5,wy=state.y+(y-h/2)/5,b=biomeAt(wx,wy);mctx.fillStyle=['#4b714b','#31594b','#93794d','#74857e','#488076','#655d47'][b];mctx.fillRect(x,y,4,4)}mctx.fillStyle='#f2d89b';mctx.beginPath();mctx.arc(w/2,h/2,3.5,0,7);mctx.fill()}
