--- function openCharacter ---
 function openCharacter(){showModal(`<div class="panel"><div class="panelhead"><div><div class="eyebrow">A new story begins</div><h2>Shape your wanderer</h2></div><button class="close" data-close>×</button></div><p class="desc">Choose how the world will know you. Your wanderer will walk every trail with you.</p><div style="height:105px;background:linear-gradient(180deg,#536a5e,#202f29);position:relative;overflow:hidden;margin-bottom:15px"><div style="position:absolute;inset:auto 0 0;height:30px;background:linear-gradient(90deg,#334b3c,#697352,#31473c)"></div><div id="avatar" style="position:absolute;left:50%;bottom:18px;transform:translateX(-50%);font-size:64px;filter:drop-shadow(0 5px 8px #111)">🧝</div><div style="position:absolute;right:9px;bottom:7px;color:#d4c48f;font-size:9px;letter-spacing:.14em">DRAG TO TURN · PREVIEW</div></div><div class="field"><label>Origin</label><div class="choices"><button class="choice active" data-gender="Male">Male</button><button class="choice" data-gender="Female">Female</button></div></div><div class="field"><label>Face & hair</label><div class="choices"><button class="choice active" data-hair="0">Ranger</button><button class="choice" data-hair="1">Seeker</button><button class="choice" data-hair="2">Elder</button></div></div><div class="field"><label>Hair color</label><div class="swatches"><button class="swatch active" data-color="#302a25" style="background:#302a25"></button><button class="swatch" data-color="#573b2d" style="background:#573b2d"></button><button class="swatch" data-color="#b99258" style="background:#b99258"></button><button class="swatch" data-color="#a54c3f" style="background:#a54c3f"></button></div></div><div class="field"><label>Starting attire</label><div class="choices"><button class="choice active" data-clothes="0">Forest leathers</button><button class="choice" data-clothes="1">Trailcloak</button><button class="choice" data-clothes="2">Ashen traveler</button></div></div><div class="field"><label>Skin tone</label><div class="swatches"><button class="swatch active" data-skin="#cfaa82" style="background:#cfaa82"></button><button class="swatch" data-skin="#a97858" style="background:#a97858"></button><button class="swatch" data-skin="#784f3d" style="background:#784f3d"></button><button class="swatch" data-skin="#e0bf9a" style="background:#e0bf9a"></button></div></div><div class="field"><label>Eyes</label><div class="choices"><button class="choice active">Hazel</button><button class="choice">Moss green</button><button class="choice">Storm grey</button></div></div><div class="field"><label>Armor & keepsake</label><div class="choices"><button class="choice active">Leather scout</button><button class="choice">Copper charm</button><button class="choice">Traveler's mantle</button></div></div><div class="field"><label>Wanderer's name</label><input id="nameInput" maxlength="16" value="${state.name}" style="width:100%;padding:11px;color:#eee8d5;background:#ffffff0b;border:1px solid #ffffff27;outline:none"></div><div class="panel-actions"><button class="btn" data-close>Back</button><button class="btn primary" id="confirmCharacter">Enter the wilds →</button></div></div>`);document.querySelectorAll('[data-gender]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-gender]').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.gender=b.dataset.gender});document.querySelectorAll('[data-hair]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-hair]').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.hair=+b.dataset.hair;document.querySelector('#avatar').textContent=['🧝','🧙','🧝‍♀️'][state.hair]});document.querySelectorAll('[data-clothes]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-clothes]').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.clothes=+b.dataset.clothes});document.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-color]').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.hairColor=b.dataset.color;document.querySelector('#avatar').style.filter=`drop-shadow(0 5px 8px #111) sepia(.35) hue-rotate(${b.dataset.color==='#a54c3f'?'-20deg':b.dataset.color==='#b99258'?'10deg':'0deg'})`});document.querySelectorAll('[data-skin]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-skin]').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.skin=b.dataset.skin});document.querySelector('#confirmCharacter').onclick=()=>{let n=document.querySelector('#nameInput').value.trim();if(n)state.name=n;closeModal();start()}}

--- function openMultiplayer ---
 function openMultiplayer(){showModal(`<div class="panel"><div class="panelhead"><div><div class="eyebrow">Together, even at the edge</div><h2>Realm gathering</h2></div><button class="close" data-close>×</button></div><p class="desc">Gather a fellowship for shared adventures. This preview offers local room creation only—no game server is connected, so other players cannot join yet.</p><div style="border:1px solid #a9d8b333;background:#6fb1900d;padding:15px;margin-bottom:13px"><div style="font-size:10px;letter-spacing:.15em;color:#a6d7bd">◉ &nbsp; PRIVATE REALM · LOCAL PREVIEW</div><div style="font:17px Cinzel;margin:9px 0 4px">The Shattered Wild</div><div style="font-size:10px;color:#a8b7aa">Co-op journey · Friends only · Safe chat</div></div><div class="choices"><button class="choice active" id="createRoom">Create a room</button><button class="choice" id="joinRoom">Join by invite</button></div><div id="roomArea" style="margin-top:13px"><div style="font-size:11px;color:#b5c3b4;line-height:1.6">Start a private party and invite your friends when online services are connected.</div></div><div class="field"><label>Safety & privacy</label><div class="choices"><button class="choice active">Friends only</button><button class="choice">Filtered chat</button><button class="choice">Block & report</button></div></div><div class="panel-actions"><button class="btn" data-close>Return</button><button class="btn primary" id="offlineStart">Explore solo →</button></div></div>`);document.querySelector('#createRoom').onclick=()=>{document.querySelector('#createRoom').classList.add('active');document.querySelector('#joinRoom').classList.remove('active');document.querySelector('#roomArea').innerHTML=`<div style="font-size:11px;color:#b5c3b4">Your invite code</div><div style="font:22px Cinzel;color:#ead39c;letter-spacing:.2em;margin:8px 0">WILD-${Math.floor(1000+Math.random()*8999)}</div><div style="font-size:10px;color:#809186">Room prepared locally · No network connection</div>`};document.querySelector('#joinRoom').onclick=()=>{document.querySelector('#joinRoom').classList.add('active');document.querySelector('#createRoom').classList.remove('active');document.querySelector('#roomArea').innerHTML='<input placeholder="Enter invite code" style="width:100%;padding:11px;color:#eee;background:#ffffff0b;border:1px solid #ffffff27"><div style="font-size:10px;color:#809186;margin-top:8px">Online matchmaking becomes available once a server is configured.</div>'};document.querySelector('#offlineStart').onclick=()=>{closeModal();if(!state.played)openCharacter()}}

--- function openSettings ---
 function openSettings(){showModal(`<div class="panel"><div class="panelhead"><div><div class="eyebrow">Make yourself at home</div><h2>Settings</h2></div><button class="close" data-close>×</button></div><div class="field"><label>Master volume</label><input class="range" type="range" min="0" max="100" value="55"></div><div class="field"><label>World ambience</label><div class="choices"><button class="choice active" data-weather="dynamic">Dynamic</button><button class="choice" data-weather="clear">Clear skies</button></div></div><div class="field"><label>Controls</label><div style="font-size:11px;line-height:1.9;color:#b5beb2">WASD / arrows — move · E — gather · Space — dodge<br>1–4 — quick slots · I — inventory · Esc — close panels<br>Touch-friendly virtual controls are available on small screens.</div></div><div class="panel-actions"><button class="btn primary" data-close>Save preferences</button></div></div>`);document.querySelectorAll('[data-weather]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-weather]').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.fixedWeather=b.dataset.weather==='clear'})}

--- function openBuild ---
 function openBuild(){showModal(`<div class="panel"><div class="panelhead"><div><div class="eyebrow">Survival · Building</div><h2>Make a camp</h2></div><button class="close" data-close>×</button></div><p class="desc">A little shelter keeps the chill at bay and gives your story a place to return to.</p><div class="recipe"><span>⌂ &nbsp; Wayfarer's lean-to<br><small>5 wildwood · 3 fieldstone</small></span><button id="buildCraft">Build · ${state.wood}/5 wood</button></div><div class="recipe"><span>◉ &nbsp; Warm berry broth<br><small>2 wild berries · restores hunger</small></span><button id="cook">Cook · ${state.berries}/2 berries</button></div><div class="panel-actions"><button class="btn" data-close>Back to the wild</button></div></div>`);document.querySelector('#buildCraft').onclick=()=>{if(state.wood>=5&&state.stone>=3){state.wood-=5;state.stone-=3;state.quest=1;state.played=true;gainXP(25);closeModal();notify('A shelter takes shape beside the trail.')}else notify('Gather 5 wood and 3 stone first.')};document.querySelector('#cook').onclick=()=>{if(state.berries>=2){state.berries-=2;state.food=Math.min(100,state.food+40);gainXP(8);notify('Warm broth · Hunger restored')}else notify('Gather 2 wild berries first.')};}

